"""
Atlas на телефоне: быстрее и красивее.

  • Голос потоком: текст ответа появляется сразу, а голос начинает играть с первых слов, пока Fish
    ещё договаривает остальное (раньше телефон ждал весь файл целиком).
  • Fish в быстром режиме (latency: balanced); если Fish не ответил — сразу голос Edge.
  • Озвучка выключена — голос вообще не делается, ответ приходит быстрее.
  • Конец фразы ловится быстрее (пауза 1 с вместо 1,2 с).
  • Новый вид: живая сфера из частиц вместо звезды — синяя в покое, бирюзовая и дышит твоим голосом,
    когда слушает, янтарная с бегущим кольцом, когда думает, сиреневая, когда говорит. Туманность на фоне,
    стеклянные списки и поля, шрифты Unbounded и Onest.

    python apply_speed_ui.py
    python apply_speed_ui.py --rollback
"""
import base64
import hashlib
import os
import re
import shutil
import subprocess
import sys
import time

for _stream in (sys.stdout, sys.stderr):
    try:
        _stream.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass

ROOT = os.path.dirname(os.path.abspath(__file__))
ORIG = {'cloud/voice_cloud.py': '42bb2532a52b07322b13432ded6402a1a803e4c2966d596c60477c05add19821', 'phone/server.py': 'c58c74302fd810a5cc5432354820daeb3a09b8d7805cb938e901150adf1d5833', 'phone/static/index.html': '7097a43c97de6c44e7258f5cc12647287f85e49121d45d5d9f555509bb0fe051', 'phone/static/sw.js': '16a2536b3aed1b25ff86866ad3ec2c83e2ff6fa69be6931f4bc7898709d62709', 'tests/test_cloud_brain.py': 'afbf0f9b4be548b1f8ff59a8987340f7e8ab8ed93509f18de226aa8331202841', 'tests/test_phone.py': 'efa3c306f2403a3bbc8351f3630010c3dc9d90ebfebdef992995429f7861e6d3'}
NEW = {'cloud/voice_cloud.py': '', 'phone/server.py': '', 'phone/static/index.html': '', 'phone/static/sw.js': '', 'tests/test_cloud_brain.py': '', 'tests/test_phone.py': ''}
TAG = "backup_speedui_"


def p(rel):
    return os.path.join(ROOT, *rel.split("/"))


def restore(backup):
    for rel, h in ORIG.items():
        if h is None:
            if os.path.exists(p(rel)):
                os.remove(p(rel))
        else:
            shutil.copy2(os.path.join(backup, *rel.split("/")), p(rel))
    print(f"Вернул прежние файлы из {backup}.")


if "--rollback" in sys.argv:
    cands = sorted(d for d in os.listdir(ROOT) if d.startswith(TAG))
    if not cands:
        sys.exit("Резервной копии нет.")
    restore(p(cands[-1]))
    sys.exit(0)
if os.path.exists(p('cloud/voice_cloud.py')) and 'def stream_speech' in open(p('cloud/voice_cloud.py'), encoding="utf-8").read():
    sys.exit("Уже установлено.")

differ = []
for rel, h in ORIG.items():
    if h is None:
        if os.path.exists(p(rel)):
            differ.append(f"{rel} — уже есть такой файл")
        continue
    if not os.path.exists(p(rel)):
        differ.append(f"{rel} — нет файла")
        continue
    got = hashlib.sha256(open(p(rel), "rb").read().replace(b"\r\n", b"\n")).hexdigest()
    if got != h:
        differ.append(rel)
if differ:
    print("  ! отличаются от версии на GitHub: " + ", ".join(differ))
    sys.exit("Эти файлы у тебя изменены — ничего не тронул. Сделай git pull (или пришли мне вывод), потом запусти снова.")

backup = p(time.strftime(TAG + "%Y%m%d_%H%M%S"))
for rel, h in ORIG.items():
    if h is not None:
        os.makedirs(os.path.dirname(os.path.join(backup, *rel.split("/"))), exist_ok=True)
        shutil.copy2(p(rel), os.path.join(backup, *rel.split("/")))
print(f"Резервная копия: {backup}")
for rel, data in NEW.items():
    os.makedirs(os.path.dirname(p(rel)) or ROOT, exist_ok=True)
    with open(p(rel), "wb") as f:
        f.write(base64.b64decode(data))
print("  ✓ голос потоком: текст сразу, звук — с первых слов")
print("  ✓ новый интерфейс: сфера частиц, туманность, стеклянные списки")

env = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUTF8="1")
suites = [f for f in sorted(os.listdir(p("tests"))) if f.startswith("test_") and f.endswith(".py")]
for suite in suites:
    try:
        r = subprocess.run([sys.executable, p("tests/" + suite)], cwd=ROOT, capture_output=True, text=True,
                           encoding="utf-8", errors="replace", timeout=300, env=env)
        out, code = r.stdout + r.stderr, r.returncode
    except subprocess.TimeoutExpired:
        out, code = "✗ тесты не закончились за 5 минут", 1
    m = re.search(r"Тестов пройдено: (\d+) из (\d+)", out)
    good = code == 0 and m and m.group(1) == m.group(2)
    print(f"  {'✓' if good else '✗'} tests/{suite}: {m.group(0) if m else 'итоговой строки нет'}")
    if not good:
        lines = out.splitlines()
        for i, ln in enumerate(lines):
            if ln.strip().startswith("✗"):
                print("      " + "\n      ".join(x.rstrip() for x in lines[i:i + 7]))
        restore(backup)
        sys.exit("✗ Проверка не прошла — всё возвращено.")
print("\nГотово. Дальше: git add -A, git commit, git push — Render обновится сам за 3–5 минут.")
print("На телефоне полностью закрой и открой Atlas (иногда дважды), чтобы подтянулась новая версия.")

